using Microsoft.Azure.Cosmos;

var client = new CosmosClient("<connection-string>");
var container = client.GetContainer("AppData", "Products");

// Create
var item = new { id = "prod-101", name = "Headphones", price = 79.99 };
await container.CreateItemAsync(item, new PartitionKey(item.id));

// Read by id
var response = await container.ReadItemAsync<dynamic>("prod-101", new PartitionKey("prod-101"));

// Replace
response.Resource.price = 69.99;
await container.ReplaceItemAsync(response.Resource, "prod-101", new PartitionKey("prod-101"));

// Delete
await container.DeleteItemAsync<dynamic>("prod-101", new PartitionKey("prod-101"));

